import { test } from 'node:test';
import assert from 'node:assert/strict';
import { esperarOperacaoLenta } from './solution.mjs';

// Função fake de espera: simula uma operação lenta (máximo 10ms).
const esperarFake = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

test('espera uma operação lenta de 5ms e devolve pronto', async () => {
  const resultado = await esperarOperacaoLenta(esperarFake, 5);
  assert.equal(resultado, 'pronto');
});

test('espera uma operação lenta de 10ms e devolve pronto', async () => {
  const resultado = await esperarOperacaoLenta(esperarFake, 10);
  assert.equal(resultado, 'pronto');
});

test('rejeita quando o tempo não é um número', async () => {
  await assert.rejects(
    () => esperarOperacaoLenta(esperarFake, '5'),
    /tempo inválido/,
  );
});

test('rejeita quando o tempo é negativo', async () => {
  await assert.rejects(
    () => esperarOperacaoLenta(esperarFake, -1),
    /tempo inválido/,
  );
});

solutionCode:
export async function esperarOperacaoLenta(esperar, ms) {
  if (typeof ms !== 'number' || ms < 0) {
    throw new Error('tempo inválido: ms deve ser um número maior ou igual a zero');
  }
  await esperar(ms);
  return 'pronto';
}
